import { serverLogger } from "../../utils/index.js";
import { runAsyncWithContextFallback, runSyncWithContextFallback } from "./context-callback.js";
const logger = serverLogger.component("tracing");
export class ContextPropagation {
    api;
    propagator;
    constructor(api, propagator) {
        this.api = api;
        this.propagator = propagator;
    }
    extractContext(headers) {
        try {
            const carrier = Object.fromEntries(headers);
            return this.api.propagation.extract(this.api.context.active(), carrier);
        }
        catch (error) {
            this.debug("Failed to extract context from headers", error);
            return undefined;
        }
    }
    injectContext(context, headers) {
        try {
            const carrier = {};
            this.api.propagation.inject(context, carrier);
            for (const [key, value] of Object.entries(carrier)) {
                headers.set(key, value);
            }
        }
        catch (error) {
            this.debug("Failed to inject context into headers", error);
        }
    }
    getActiveContext() {
        try {
            return this.api.context.active();
        }
        catch (error) {
            this.debug("Failed to get active context", error);
            return undefined;
        }
    }
    withActiveSpan(span, fn) {
        if (!span)
            return fn();
        const spanContext = this.resolveSpanContext(span);
        if (!spanContext)
            return fn();
        return runAsyncWithContextFallback((callback) => this.api.context.with(spanContext, callback), fn, (error) => this.debug("Failed to activate span context", error));
    }
    withSpan(name, fn, startSpan, endSpan) {
        const span = this.startSpanSafely(name, startSpan);
        const spanContext = this.resolveSpanContext(span);
        try {
            const result = spanContext
                ? runSyncWithContextFallback((callback) => this.api.context.with(spanContext, callback), () => fn(span), (error) => this.debug("Failed to activate span context", error))
                : fn(span);
            this.endSpanSafely(span, endSpan);
            return result;
        }
        catch (error) {
            this.endSpanSafely(span, endSpan, [error]);
            throw error;
        }
    }
    async withSpanAsync(name, fn, startSpan, endSpan) {
        const span = this.startSpanSafely(name, startSpan);
        const spanContext = this.resolveSpanContext(span);
        try {
            const result = spanContext
                ? await runAsyncWithContextFallback((callback) => this.api.context.with(spanContext, callback), () => fn(span), (error) => this.debug("Failed to activate span context", error))
                : await fn(span);
            this.endSpanSafely(span, endSpan);
            return result;
        }
        catch (error) {
            this.endSpanSafely(span, endSpan, [error]);
            throw error;
        }
    }
    resolveSpanContext(span) {
        const activeContext = this.getActiveContext();
        if (!activeContext || !span)
            return activeContext;
        try {
            return this.api.trace.setSpan(activeContext, span);
        }
        catch (error) {
            this.debug("Failed to associate span with context", error);
            return activeContext;
        }
    }
    startSpanSafely(name, startSpan) {
        try {
            return startSpan(name);
        }
        catch (error) {
            this.debug("Failed to start span", error);
            return null;
        }
    }
    endSpanSafely(span, endSpan, failure = []) {
        try {
            if (failure.length > 0)
                endSpan(span, failure[0]);
            else
                endSpan(span);
        }
        catch (endError) {
            this.debug("Failed to end span", endError);
        }
    }
    debug(message, error) {
        try {
            logger.debug(message, error);
        }
        catch (_) {
            /* expected: logging failures must not affect application work */
        }
    }
}
